from pathlib import Path
from xml.sax.saxutils import escape
import json,zipfile,xml.etree.ElementTree as E
b=Path('/root/HorizonNetwork/artifacts/horizon-network-operations-policy');d=json.loads((b/'policy-content.json').read_text())
ns='xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"'
def run(text,bold=False):return '<w:r>'+('<w:rPr><w:b/></w:rPr>'if bold else '')+'<w:t xml:space="preserve">'+escape(text)+'</w:t></w:r>'
def para(text='',style=None,bold=False):return '<w:p>'+('<w:pPr><w:pStyle w:val="'+style+'"/></w:pPr>'if style else '')+run(text,bold)+'</w:p>'
def clause(num,text):return '<w:p><w:pPr><w:pStyle w:val="Body"/></w:pPr>'+run(num+'  ',True)+run(text)+'</w:p>'
body=para(d['title'],'Title')+para('WORKING DRAFT — NOT YET APPROVED OR EFFECTIVE','Subtitle')
rows=[('Company','Horizon Network Limited'),('Policy owner',d['owner']),('Version',d['version']),('Draft prepared',d['date']),('Effective from','Pending approval'),('Review date','To be agreed')]
body+='<w:tbl><w:tblPr><w:tblW w:w="9638" w:type="dxa"/><w:tblBorders><w:bottom w:val="single" w:sz="4" w:color="DDD6E8"/></w:tblBorders></w:tblPr><w:tblGrid><w:gridCol w:w="2400"/><w:gridCol w:w="7238"/></w:tblGrid>'
for label,value in rows:body+='<w:tr><w:tc><w:tcPr><w:tcW w:w="2400" w:type="dxa"/><w:shd w:fill="F5F1FA"/></w:tcPr>'+para(label,'Meta',True)+'</w:tc><w:tc><w:tcPr><w:tcW w:w="7238" w:type="dxa"/></w:tcPr>'+para(value,'Meta')+'</w:tc></w:tr>'
body+='</w:tbl>'+para('Prepared from the supplied notes. Drafting decisions requiring confirmation are listed at the end.','Intro')
for i,(title,clauses) in enumerate(d['articles'],1):
 body+=para(f'Article {i} — {title}','Heading1')
 body+=''.join(clause(n,t)for n,t in clauses)
body+='<w:p><w:pPr><w:pageBreakBefore/></w:pPr></w:p>'+para('Drafting decisions to confirm','Heading1')+para('Review notes only; these are not operative policy provisions.','Intro')
body+=''.join(para('• '+note,'Body')for note in d['notes'])
body+='<w:sectPr><w:headerReference w:type="default" r:id="rHeader"/><w:footerReference w:type="default" r:id="rFooter"/><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1900" w:right="1134" w:bottom="1134" w:left="1134" w:header="567" w:footer="567"/></w:sectPr>'
doc='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document '+ns+'><w:body>'+body+'</w:body></w:document>'
header='''<?xml version="1.0" encoding="UTF-8"?><w:hdr '''+ns+''' xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:p><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="3000000" cy="627640"/><wp:docPr id="1" name="Horizon Network letterhead" descr="Horizon Network wordmark with multicolour stripe"/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="horizon-network-wordmark.png"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rLogo"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="3000000" cy="627640"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p></w:hdr>'''
footer='<?xml version="1.0" encoding="UTF-8"?><w:ftr '+ns+'><w:p><w:pPr><w:pStyle w:val="Footer"/><w:tabs><w:tab w:val="right" w:pos="9638"/></w:tabs><w:pBdr><w:top w:val="single" w:sz="4" w:color="DDD6E8"/></w:pBdr></w:pPr>'+run('Horizon Network Limited · Operations Policy · Draft 0.1')+'<w:r><w:tab/></w:r>'+run('Page ')+'<w:fldSimple w:instr="PAGE">'+run('1')+'</w:fldSimple>'+run(' of ')+'<w:fldSimple w:instr="NUMPAGES">'+run('1')+'</w:fldSimple></w:p></w:ftr>'
styles='''<?xml version="1.0" encoding="UTF-8"?><w:styles '''+ns+'''><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="22"/><w:color w:val="1A1A1A"/><w:lang w:val="en-GB"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after="100" w:line="276" w:lineRule="auto"/><w:widowControl/></w:pPr></w:pPrDefault></w:docDefaults><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style><w:style w:type="paragraph" w:styleId="Body"><w:name w:val="Body"/></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:pPr><w:keepNext/><w:spacing w:after="180"/></w:pPr><w:rPr><w:b/><w:sz w:val="44"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:pPr><w:keepNext/><w:outlineLvl w:val="0"/><w:spacing w:before="240" w:after="140"/></w:pPr><w:rPr><w:b/><w:color w:val="5514B4"/><w:sz w:val="27"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/><w:pPr><w:keepNext/></w:pPr><w:rPr><w:b/><w:sz w:val="18"/><w:color w:val="5514B4"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Meta"><w:name w:val="Metadata"/><w:rPr><w:sz w:val="19"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Intro"><w:name w:val="Introduction"/><w:rPr><w:i/><w:color w:val="606070"/><w:sz w:val="20"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Footer"><w:name w:val="Footer"/><w:rPr><w:sz w:val="15"/><w:color w:val="6E6F7E"/></w:rPr></w:style></w:styles>'''
relsbase='http://schemas.openxmlformats.org/package/2006/relationships';office='http://schemas.openxmlformats.org/officeDocument/2006/relationships/'
rels=lambda rs:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="'+relsbase+'">'+''.join('<Relationship Id="'+i+'" Type="'+office+t+'" Target="'+v+'"/>'for i,t,v in rs)+'</Relationships>'
ct='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/>'+''.join('<Override PartName="/word/'+name+'.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.'+typ+'+xml"/>'for name,typ in [('document','document.main'),('styles','styles'),('header1','header'),('footer1','footer'),('settings','settings')])+'</Types>'
parts={'[Content_Types].xml':ct,'_rels/.rels':rels([('rDoc','officeDocument','word/document.xml')]),'word/document.xml':doc,'word/styles.xml':styles,'word/header1.xml':header,'word/footer1.xml':footer,'word/settings.xml':'<w:settings '+ns+'><w:updateFields w:val="true"/></w:settings>','word/_rels/document.xml.rels':rels([('rHeader','header','header1.xml'),('rFooter','footer','footer1.xml'),('rStyles','styles','styles.xml'),('rSettings','settings','settings.xml')]),'word/_rels/header1.xml.rels':rels([('rLogo','image','media/horizon-network-wordmark.png')])}
for value in parts.values():E.fromstring(value)
out=b/'Horizon-Network-Operations-Policy-Draft-0.1.docx'
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED)as z:
 for name,value in parts.items():z.writestr(name,value)
 z.writestr('word/media/horizon-network-wordmark.png',Path('/root/HorizonNetwork/docs-site/lib/pdf-assets/horizon-network-wordmark.png').read_bytes())
print(out)
